INSERT INTO channels VALUES('tiktok','TikTok',true),('shopee','Shopee',true);
INSERT INTO metric_mapping_versions(id,channel_id,label,confirmed,is_demo) VALUES('tiktok-source-v1','tiktok','Label sumber TikTok; canonical belum dikonfirmasi',true,false),('shopee-source-v1','shopee','Label sumber Shopee; canonical belum dikonfirmasi',true,false),('tiktok-demo-v1','tiktok','Synthetic demo contract',true,true),('shopee-demo-v1','shopee','Synthetic demo contract',true,true);
INSERT INTO metric_definitions(mapping_version,key,label,unit,kind,aggregation,required,canonical_column,canonical_confirmed)
SELECT m.id,k.key,k.label,k.unit,k.kind,k.agg,(k.key IN('sales','orders','views') OR m.channel_id='shopee' AND k.key IN('buyers','viewers','watch_duration')),CASE WHEN m.is_demo THEN k.col ELSE NULL END,m.is_demo AND k.col IS NOT NULL FROM metric_mapping_versions m CROSS JOIN (VALUES
('sales','Penjualan / Perolehan GMV','IDR','money','sum',16),('estimated_sales','Perkiraan GMV','IDR','money','separate',NULL),('impressions','Impresi','count','count','sum',18),('views','Views','count','count','sum',19),('orders','Pesanan','count','count','sum',20),('buyers','Pembeli per sesi','count','count','per_session',21),('watch_duration','Rata-rata tonton','seconds','duration','weighted_only',22),('viewers','Penonton sumber','count','count','per_session',NULL),('current_viewers','Penonton saat screenshot','count','count','snapshot',NULL),('source_aov','AOV sumber','IDR','money','source',NULL),('product_clicks','Klik produk','count','count','sum',25),('new_followers','Pengikut baru','count','count','sum',26),('likes','Likes','count','count','sum',27),('comments','Komentar','count','count','sum',28),('shares','Dibagikan','count','count','sum',29),('units_sold','Produk terjual','count','count','sum',NULL),('add_to_cart','Tambah ke keranjang','count','count','sum',NULL),('active_viewers','Penonton aktif','count','count','source',NULL),('peak_viewers','Penonton tertinggi','count','count','max',NULL),('source_ctr','CTR sumber','ratio','ratio','source',NULL),('source_ctor','CTOR sumber','ratio','ratio','source',NULL),('source_click_rate','Rasio klik sumber','ratio','ratio','source',NULL),('source_roi','ROI GMV Max sumber','multiple','money','source',NULL),('ad_cost','Biaya iklan','IDR','money','sum',NULL),('sales_per_mille','Penjualan per mil sumber','IDR','money','source',NULL)
) AS k(key,label,unit,kind,agg,col);
DELETE FROM metric_definitions WHERE mapping_version LIKE 'shopee-%' AND key IN('impressions','estimated_sales','product_clicks','new_followers','source_roi','source_ctr','source_ctor','ad_cost','current_viewers');
